def reserve(stock, want):
    return stock + want

def loss(a1, a2):
    return a1 + a2 - reserve(a1 + a2, a1)

def parts(total, n):
    return total // n

def loss(a1, a2):
    return parts(a1 + a2, 3) * 3 - (a1 + a2)

def quorum(cast, total):
    return cast * 2 - total

def loss(a1, a2):
    return a1 - a2

def overlap(start1, end1, start2, end2):
    return 1 if start2 < end1 else 0

def loss(a1, a2):
    return a2 - a1 - 1

def penalty(mins, cap):
    return mins * 10

def loss(a1, a2):
