def score(base, bonus):
    return base + bonus

def loss(a1, a2):
    return 850 - score(a1, a2)

def carry(days, limit):
    return days

def loss(a1, a2):
    return a2 - carry(a1, a2)

def workers(load, cap):
    return load - 1

def loss(a1, a2):
    return workers(a1, a2) - 1

def disc(qty):
    return qty * 2 // 100 if qty < 100 else 0

def loss(a1, a2):
    return disc(a1 + a2) - disc(a1)

def norm(price, tick):
    return price // (tick + 1) * (tick + 1)

def loss(a1, a2):
    return norm(a1 * 100, a2 * 10) - (a1 * 100 // (a2 * 10) * (a2 * 10))
